/**
 * Writes the XML prefix.
 */
@Override
public void startDocument() throws SAXException {
    if (encoding != null) {
        write("<?xml version=\"1.0\" encoding=\"");
        write(encoding);
        write("\"?>\n");
    }
    currentElement = null;
    namespaces.clear();
}
